// =============================================
// STEP 1: Confirm signal with Claude (2nd opinion)
// =============================================
const signal = $input.first().json;

const SYSTEM_PROMPT = `Ты — риск-менеджер торговой системы по методу Герчика.
Тебе дали торговый сигнал для подтверждения.

ПРОВЕРЬ:
1) Сигнал НЕ противоречит тренду на старшем ТФ?
2) Уровень действительно сильный (минимум 2 касания)?
3) Есть подтверждение на младшем ТФ (паттерн разворота)?
4) Risk/reward >= 3?
5) Стоп-лосс стоит за уровнем (за тенью свечи)?

ФОРМАТ ОТВЕТА строго JSON:
{
  "confirmed": true|false,
  "adjusted_entry": number или null,
  "adjusted_stop": number или null,
  "adjusted_tp1": number или null,
  "risk_score": 1-10,
  "reasoning": "объяснение на русском"
}

ВАЖНО: Отвечай ТОЛЬКО валидным JSON.`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${$env.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514',
      max_tokens: 512,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: `Подтверди сигнал:\n${JSON.stringify(signal, null, 2)}` }
      ]
    }
  });

  const text = response.choices[0].message.content;
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1];

  const confirmation = JSON.parse(jsonStr.trim());

  return [{
    json: {
      ...signal,
      _confirmation: confirmation,
      _confirmed: confirmation.confirmed === true && confirmation.risk_score <= 7,
      entry_price: confirmation.adjusted_entry || signal.entry_price,
      stop_loss: confirmation.adjusted_stop || signal.stop_loss,
      take_profit_1: confirmation.adjusted_tp1 || signal.take_profit_1
    }
  }];
} catch(e) {
  // Claude unavailable — DO NOT TRADE
  return [{
    json: {
      ...signal,
      _confirmed: false,
      _confirmation: { confirmed: false, reasoning: `OpenRouter API error: ${e.message}` },
      _error: true
    }
  }];
}

// =============================================
// STEP 2: Check balance & open positions count
// =============================================
const signal = $input.first().json;
const crypto = require('crypto');

const isTestnet = ($env.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;
const MAX_POSITIONS = parseInt($env.MAX_OPEN_POSITIONS || '3');

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey,
      'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp,
      'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

// Get wallet balance
const balResp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
let usdtBalance = 0;
try {
  const coins = balResp.result.list[0].coin;
  const usdt = coins.find(c => c.coin === 'USDT');
  usdtBalance = usdt ? parseFloat(usdt.walletBalance) : 0;
} catch(e) { usdtBalance = 0; }

// Get open orders count
const ordResp = await signedGet.call(this, '/v5/order/realtime', {
  category: signal.market_type === 'futures' ? 'linear' : 'spot',
  settleCoin: 'USDT'
});
const openPositions = (ordResp.result?.list || []).length;

// Check daily P&L (from Risk Guardian store)
const store = $getWorkflowStaticData('global');
const dailyLoss = store.dailyLoss || 0;
const maxDailyLoss = parseFloat($env.MAX_DAILY_LOSS || '3');
const isStopped = dailyLoss >= maxDailyLoss;

return [{
  json: {
    ...signal,
    usdtBalance,
    openPositions,
    maxPositions: MAX_POSITIONS,
    canTrade: openPositions < MAX_POSITIONS && usdtBalance > 10 && !isStopped,
    dailyLoss,
    isStopped,
    baseUrl
  }
}];

// =============================================
// STEP 3: Calculate position size (1% risk)
// =============================================
const data = $input.first().json;
const riskPercent = parseFloat($env.MAX_RISK_PER_TRADE || '1');

const riskAmount = data.usdtBalance * (riskPercent / 100);
const stopDistance = Math.abs(data.entry_price - data.stop_loss);

if (stopDistance === 0) {
  return [{ json: { ...data, _skip: true, _skipReason: 'Stop distance is 0' } }];
}

const positionSize = riskAmount / stopDistance;
const positionValue = positionSize * data.entry_price;

// Safety: don't use more than 20% of balance on one trade
const maxPositionValue = data.usdtBalance * 0.2;
const adjustedSize = positionValue > maxPositionValue 
  ? maxPositionValue / data.entry_price 
  : positionSize;

return [{
  json: {
    ...data,
    positionSize: parseFloat(adjustedSize.toFixed(6)),
    positionValue: parseFloat((adjustedSize * data.entry_price).toFixed(2)),
    riskAmount: parseFloat(riskAmount.toFixed(2)),
    riskPercent,
    _skip: false
  }
}];

// =============================================
// STEP 4: Place order + SL + TP on Bybit
// =============================================
const data = $input.first().json;
const crypto = require('crypto');

if (data._skip) {
  return [{ json: { ...data, orderResult: 'SKIPPED', orderReason: data._skipReason } }];
}

const apiKey = $env.BYBIT_API_KEY;
const apiSecret = $env.BYBIT_API_SECRET;
const baseUrl = data.baseUrl;

async function signedPost(endpoint, body) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const bodyStr = JSON.stringify(body);
  const preSign = timestamp + apiKey + recvWindow + bodyStr;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');

  return this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}${endpoint}`,
    headers: {
      'X-BAPI-API-KEY': apiKey,
      'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp,
      'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body
  });
}

const category = data.market_type === 'futures' ? 'linear' : 'spot';
const isSpot = category === 'spot';

try {
  // Main order with SL/TP
  const orderPayload = {
    category,
    symbol: data.pair,
    side: data.action, // Buy or Sell
    orderType: 'Limit',
    qty: data.positionSize.toString(),
    price: data.entry_price.toString(),
    timeInForce: 'GTC',
    ...(isSpot ? {} : {
      stopLoss: data.stop_loss.toString(),
      takeProfit: data.take_profit_1.toString(),
      tpslMode: 'Full',
      tpOrderType: 'Limit',
      slOrderType: 'Market'
    })
  };

  const orderResp = await signedPost.call(this, '/v5/order/create', orderPayload);

  // For spot — place separate SL order via conditional order
  let slOrderId = null;
  if (isSpot && orderResp.retCode === 0) {
    const slSide = data.action === 'Buy' ? 'Sell' : 'Buy';
    const slPayload = {
      category: 'spot',
      symbol: data.pair,
      side: slSide,
      orderType: 'Market',
      qty: data.positionSize.toString(),
      triggerPrice: data.stop_loss.toString(),
      triggerDirection: data.action === 'Buy' ? 2 : 1, // 1=rise, 2=fall
      orderFilter: 'StopOrder'
    };
    try {
      const slResp = await signedPost.call(this, '/v5/order/create', slPayload);
      slOrderId = slResp.result?.orderId || null;
    } catch(e) { /* SL order failed — will alert */ }
  }

  return [{
    json: {
      ...data,
      orderResult: orderResp.retCode === 0 ? 'SUCCESS' : 'FAILED',
      orderId: orderResp.result?.orderId || 'N/A',
      slOrderId,
      retCode: orderResp.retCode,
      retMsg: orderResp.retMsg
    }
  }];
} catch(e) {
  return [{
    json: {
      ...data,
      orderResult: 'ERROR',
      orderId: 'N/A',
      retMsg: e.message
    }
  }];
}

// =============================================
// STEP 5: Format Telegram notification
// =============================================
const data = $input.first().json;

const success = data.orderResult === 'SUCCESS';
const emoji = success ? '✅' : '❌';
const sideEmoji = data.action === 'Buy' ? '🟢 LONG' : '🔴 SHORT';

let message = `${emoji} <b>Trade Executor</b>\n\n`;
message += `${sideEmoji} <b>${data.pair}</b>\n\n`;

if (success) {
  message += `<b>Вход:</b> <code>${data.entry_price}</code>\n`;
  message += `<b>Стоп:</b> <code>${data.stop_loss}</code>\n`;
  message += `<b>TP1:</b> <code>${data.take_profit_1}</code>\n`;
  message += `<b>TP2:</b> <code>${data.take_profit_2}</code>\n`;
  message += `<b>TP3:</b> <code>${data.take_profit_3}</code>\n\n`;
  message += `<b>Размер:</b> ${data.positionSize} (~$${data.positionValue})\n`;
  message += `<b>Риск:</b> $${data.riskAmount} (${data.riskPercent}%)\n`;
  message += `<b>R:R:</b> ${data.risk_reward_ratio}\n`;
  message += `<b>Уверенность:</b> ${data.confidence}%\n`;
  message += `<b>Order ID:</b> <code>${data.orderId}</code>\n\n`;
  message += `<b>Причина:</b> ${data.reasoning}\n`;
  message += `<b>Подтверждение:</b> ${data._confirmation?.reasoning || 'N/A'}\n`;
} else {
  message += `<b>Ошибка:</b> ${data.retMsg || data.orderResult}\n`;
  if (data._skipReason) message += `<b>Причина пропуска:</b> ${data._skipReason}\n`;
}

message += `\n<b>Баланс:</b> $${data.usdtBalance?.toFixed(2)}\n`;
message += `<b>Позиций:</b> ${data.openPositions}/${data.maxPositions}\n`;
message += `⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message } }];
